const html="<!doctype html><html lang=\"zh-Hant\"><head><meta charset=\"UTF-8\"/><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"/><title>社團搜尋自動化系統</title><meta name=\"description\" content=\"輸入關鍵字後，自動搜尋社團並整理成可下載的表格。\"/><link rel=\"stylesheet\" href=\"./styles.css\"/></head><body><main class=\"app-shell\"><section class=\"hero card\"><p class=\"eyebrow\">Group Finder System</p><h1>社團搜尋自動化系統</h1><p class=\"lede\">輸入任意關鍵字，自動比對多種社團主題、排序相關結果，並輸出成 Excel 可直接開啟的 CSV。</p></section><section class=\"controls card\"><input id=\"keyword\" placeholder=\"例如：親子、咖啡、投資、台中、攝影、二手\" /><select id=\"platform\"><option value=\"all\">全部平台</option><option value=\"facebook\">Facebook 社團</option><option value=\"discord\">Discord 社群</option><option value=\"reddit\">Reddit Community</option><option value=\"line\">LINE 社群</option><option value=\"telegram\">Telegram 群組</option></select><select id=\"region\"><option value=\"all\">全部地區</option><option value=\"tw\">台灣</option><option value=\"hk\">香港</option><option value=\"global\">國際</option><option value=\"sea\">東南亞</option></select><div class=\"actions\"><button id=\"searchBtn\" class=\"primary\">開始搜尋</button><button id=\"downloadBtn\" class=\"secondary\" disabled>下載 CSV</button></div></section><section class=\"card results-panel\"><div class=\"results-head\"><div><p class=\"eyebrow\">搜尋結果</p><h2 id=\"summaryTitle\">尚未搜尋</h2></div><div class=\"results-meta\"><div id=\"stats\" class=\"stats\">等待輸入關鍵字</div><div id=\"datasetStats\" class=\"dataset-stats\">0 筆資料</div></div></div><div class=\"table-wrap\"><table><thead><tr><th>相關度</th><th>社團名稱</th><th>平台</th><th>地區</th><th>網址</th><th>標籤</th></tr></thead><tbody id=\"resultsBody\"><tr><td colspan=\"6\" class=\"empty\">輸入關鍵字後按下「開始搜尋」</td></tr></tbody></table></div></section><section class=\"card import-panel\"><textarea id=\"jsonInput\" placeholder='貼上 JSON 陣列，例如 [{\"name\":\"...\",\"platform\":\"facebook\",...}]'></textarea><div class=\"import-row\"><input id=\"fileInput\" type=\"file\" accept=\".json,application/json\" /><button id=\"importBtn\" class=\"secondary\">匯入資料</button><button id=\"resetBtn\" class=\"secondary\">還原範例資料</button></div><div id=\"importStatus\" class=\"import-status\">目前使用內建範例資料。</div></section></main><script src=\"./script.js\"></script></body></html>";
const css="body{margin:0;padding:28px;font-family:system-ui,sans-serif;background:#f4f7fb;color:#0f172a}.card{background:rgba(255,255,255,.85);border:1px solid rgba(15,23,42,.1);border-radius:24px;box-shadow:0 24px 80px rgba(15,23,42,.08)}.app-shell{max-width:1200px;margin:0 auto;display:grid;gap:18px}.hero,.controls,.results-panel,.import-panel{padding:24px}.eyebrow{margin:0 0 12px;font-size:12px;letter-spacing:.26em;text-transform:uppercase;color:#1d4ed8;font-weight:800}h1{margin:0;font-size:clamp(2.4rem,6vw,5rem);line-height:.95;letter-spacing:-.06em}.lede{max-width:58ch;color:#5b6475;line-height:1.7}.controls{display:grid;gap:16px;grid-template-columns:1.4fr .9fr .9fr .8fr}input,select,textarea,button{font:inherit}input,select,textarea{width:100%;padding:14px 16px;border-radius:16px;border:1px solid rgba(15,23,42,.12);background:#fff;outline:none}button{border:0;border-radius:16px;padding:14px 18px;font-weight:800;cursor:pointer}.primary{background:linear-gradient(135deg,#0f172a,#1d4ed8,#7c3aed);color:#fff}.secondary{background:#fff;border:1px solid rgba(15,23,42,.12)}.actions{display:flex;gap:12px}.results-head{display:flex;justify-content:space-between;gap:16px;align-items:end;margin-bottom:16px}.stats{color:#5b6475;font-weight:700}.dataset-stats{color:#1d4ed8;font-weight:800;font-size:.88rem}.table-wrap{overflow:auto;border:1px solid rgba(15,23,42,.1);border-radius:18px;background:rgba(255,255,255,.75)}table{width:100%;border-collapse:collapse;min-width:980px}th,td{padding:14px 16px;text-align:left;border-bottom:1px solid rgba(15,23,42,.08);vertical-align:top}th{background:rgba(15,23,42,.02);font-size:.78rem;text-transform:uppercase;letter-spacing:.12em;color:#5b6475}.badge{display:inline-flex;padding:6px 10px;border-radius:999px;background:rgba(29,78,216,.08);color:#1e3a8a;font-weight:800;font-size:.8rem;margin-right:6px;margin-bottom:6px}.empty{text-align:center;padding:42px 20px;color:#5b6475}.url{color:#1d4ed8;word-break:break-all}.import-panel{display:grid;gap:12px}.import-status{font-weight:700;color:#5b6475}@media (max-width:980px){body{padding:14px}.controls,.results-head{grid-template-columns:1fr;display:grid}.actions{flex-direction:column}.results-head{align-items:start}}";
const script="const seed=[{\"name\":\"台北親子生活交流\",\"platform\":\"facebook\",\"region\":\"tw\",\"url\":\"https://www.facebook.com/groups/taipei.parents.life\",\"tags\":[\"親子\",\"台北\",\"育兒\"],\"members\":\"48K\",\"desc\":\"親子活動、育兒資訊與家庭生活交流。\"},{\"name\":\"台中二手好物交易\",\"platform\":\"facebook\",\"region\":\"tw\",\"url\":\"https://www.facebook.com/groups/taichung.secondhand.market\",\"tags\":[\"二手\",\"台中\",\"交易\"],\"members\":\"85K\",\"desc\":\"二手家具、家電、書籍與生活用品交易。\"},{\"name\":\"高雄咖啡烘焙同好會\",\"platform\":\"facebook\",\"region\":\"tw\",\"url\":\"https://www.facebook.com/groups/kaohsiung.coffee.roast\",\"tags\":[\"咖啡\",\"高雄\",\"烘焙\"],\"members\":\"21K\",\"desc\":\"咖啡豆、手沖、烘焙與店家交流。\"},{\"name\":\"台灣投資理財討論區\",\"platform\":\"facebook\",\"region\":\"tw\",\"url\":\"https://www.facebook.com/groups/tw.investment.forum\",\"tags\":[\"投資\",\"理財\",\"股票\"],\"members\":\"120K\",\"desc\":\"股票、ETF、資產配置與理財分享。\"},{\"name\":\"台北攝影創作社\",\"platform\":\"facebook\",\"region\":\"tw\",\"url\":\"https://www.facebook.com/groups/taipei.photo.creators\",\"tags\":[\"攝影\",\"台北\",\"創作\"],\"members\":\"37K\",\"desc\":\"人像、街拍、器材與作品交流。\"},{\"name\":\"台灣寵物交流社\",\"platform\":\"facebook\",\"region\":\"tw\",\"url\":\"https://www.facebook.com/groups/tw.pet.community\",\"tags\":[\"寵物\",\"狗\",\"貓\"],\"members\":\"64K\",\"desc\":\"毛孩照護、認養、疾病與日常分享。\"},{\"name\":\"健身重訓交流圈\",\"platform\":\"facebook\",\"region\":\"tw\",\"url\":\"https://www.facebook.com/groups/fitness.training.club\",\"tags\":[\"健身\",\"重訓\",\"增肌\"],\"members\":\"92K\",\"desc\":\"訓練菜單、飲食與健身進度分享。\"},{\"name\":\"台灣旅遊秘境分享\",\"platform\":\"facebook\",\"region\":\"tw\",\"url\":\"https://www.facebook.com/groups/tw.travel.secret\",\"tags\":[\"旅遊\",\"秘境\",\"景點\"],\"members\":\"58K\",\"desc\":\"國內旅遊、住宿、景點與行程推薦。\"},{\"name\":\"香港親子玩樂社\",\"platform\":\"facebook\",\"region\":\"hk\",\"url\":\"https://www.facebook.com/groups/hk.parents.fun\",\"tags\":[\"親子\",\"香港\",\"活動\"],\"members\":\"33K\",\"desc\":\"香港親子活動、學校資訊與家庭攻略。\"},{\"name\":\"Singapore Food Hunters\",\"platform\":\"facebook\",\"region\":\"sea\",\"url\":\"https://www.facebook.com/groups/singapore.food.hunters\",\"tags\":[\"美食\",\"新加坡\",\"餐廳\"],\"members\":\"71K\",\"desc\":\"東南亞美食、餐廳與開箱推薦。\"}];let groups=[...seed];const $=id=>document.getElementById(id);const state={results:[]};const tokenize=t=>t.toLowerCase().trim().split(/[\\\\s,，、;；/|]+/).filter(Boolean);const scoreGroup=(g,q,p,r)=>{if(!q.trim())return 0;const hay=[g.name,g.desc,g.url,...g.tags].join(\" \").toLowerCase();let s=0;for(const token of tokenize(q)){if(hay.includes(token))s+=7;if(g.name.toLowerCase().includes(token))s+=5;if(g.desc.toLowerCase().includes(token))s+=3;for(const tag of g.tags)if(tag.toLowerCase().includes(token))s+=4}if(p!==\"all\"&&g.platform===p)s+=6;if(r!==\"all\"&&g.region===r)s+=6;if(g.name.toLowerCase().includes(q.toLowerCase()))s+=10;if(g.desc.toLowerCase().includes(q.toLowerCase()))s+=4;s+=Math.min(Number(g.members.replace(/\\\\D/g,\"\"))||0,200000)/30000;return s};const renderDatasetStats=()=>{$(\"datasetStats\").textContent=groups.length+\" 筆資料 · \"+new Set(groups.map(g=>g.platform)).size+\" 種平台 · \"+new Set(groups.map(g=>g.region)).size+\" 個區域\"};const renderImportStatus=(message,tone=\"info\")=>{$(\"importStatus\").textContent=message;$(\"importStatus\").dataset.tone=tone};const renderResults=()=>{const keyword=$(\"keyword\").value.trim();const platform=$(\"platform\").value;const region=$(\"region\").value;const ranked=groups.map(group=>({...group,score:scoreGroup(group,keyword,platform,region)})).filter(group=>group.score>0).sort((a,b)=>b.score-a.score||Number(String(b.members).replace(/\\\\D/g,\"\"))-Number(String(a.members).replace(/\\\\D/g,\"\")));state.results=ranked;$(\"downloadBtn\").disabled=ranked.length===0;$(\"summaryTitle\").textContent=keyword?\"關鍵字「\"+keyword+\"」的結果\":\"尚未搜尋\";$(\"stats\").textContent=ranked.length?\"找到 \"+ranked.length+\" 筆結果，已按相關度排序\":keyword?\"沒有符合條件的結果，請換一個關鍵字或放寬篩選\":\"等待輸入關鍵字\";const tbody=$(\"resultsBody\");if(!keyword){tbody.innerHTML='<tr><td colspan=\"6\" class=\"empty\">輸入關鍵字後按下「開始搜尋」</td></tr>';return}if(!ranked.length){tbody.innerHTML='<tr><td colspan=\"6\" class=\"empty\">沒有找到符合條件的社團</td></tr>';return}tbody.innerHTML=ranked.slice(0,50).map((group,index)=>'<tr><td><strong>#'+(index+1)+'</strong><br><small>'+group.score.toFixed(1)+'</small></td><td><strong>'+group.name+'</strong><br><span class=\"muted\">'+group.desc+'</span></td><td><span class=\"badge\">'+group.platform+'</span><br><small>'+group.members+' 成員</small></td><td>'+group.region+'</td><td><a class=\"url\" href=\"'+group.url+'\" target=\"_blank\" rel=\"noreferrer\">'+group.url+'</a></td><td>'+group.tags.map(tag=>'<span class=\"badge\">'+tag+'</span>').join('')+'</td></tr>').join('')};const csvEscape=value=>'\"'+String(value??'').replace(/\"/g,'\"\"')+'\"';const downloadCSV=()=>{const rows=[[\"排名\",\"相關度\",\"社團名稱\",\"平台\",\"地區\",\"網址\",\"成員數\",\"標籤\",\"描述\"],...state.results.slice(0,200).map((group,index)=>[index+1,group.score.toFixed(1),group.name,group.platform,group.region,group.url,group.members,group.tags.join(\" | \"),group.desc])];const csv=\"\\\\ufeff\"+rows.map(row=>row.map(csvEscape).join(\",\")).join(\"\\\\n\");const blob=new Blob([csv],{type:\"text/csv;charset=utf-8;\"});const url=URL.createObjectURL(blob);const a=document.createElement(\"a\");a.href=url;a.download=\"group-finder-\"+new Date().toISOString().slice(0,10)+\".csv\";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};function importFromTextarea(){const raw=$(\"jsonInput\").value.trim();if(!raw){renderImportStatus(\"請先貼上 JSON 資料，再按匯入。\",\"error\");return}try{const parsed=JSON.parse(raw);const incoming=Array.isArray(parsed)?parsed.filter(Boolean).map(item=>({name:String(item.name??\"\").trim(),platform:String(item.platform??\"all\").trim().toLowerCase(),region:String(item.region??\"global\").trim().toLowerCase(),url:String(item.url??\"\").trim(),tags:Array.isArray(item.tags)?item.tags.map(tag=>String(tag).trim()).filter(Boolean):[],members:String(item.members??\"0\"),desc:String(item.desc??\"\").trim()})).filter(item=>item.name&&item.url):[];if(!incoming.length){renderImportStatus(\"JSON 有讀到，但沒有有效社團資料。\",\"error\");return}groups=[...groups,...incoming];renderDatasetStats();renderImportStatus(\"成功匯入 \"+incoming.length+\" 筆資料，目前共 \"+groups.length+\" 筆。\",\"success\");renderResults()}catch(error){renderImportStatus(\"JSON 格式錯誤：\"+error.message,\"error\")}}function importFromFile(file){const reader=new FileReader();reader.onload=()=>{$(\"jsonInput\").value=String(reader.result??\"\");importFromTextarea()};reader.readAsText(file,\"utf-8\")}function resetDataset(){groups=[...seed];$(\"jsonInput\").value=\"\";renderImportStatus(\"已還原為內建範例資料。\",\"success\");renderDatasetStats();renderResults()}document.querySelectorAll(\".chip\").forEach(chip=>chip.addEventListener(\"click\",()=>{$(\"keyword\").value=chip.dataset.keyword||\"\";renderResults()}));$(\"searchBtn\").addEventListener(\"click\",renderResults);$(\"downloadBtn\").addEventListener(\"click\",downloadCSV);$(\"importBtn\").addEventListener(\"click\",importFromTextarea);$(\"resetBtn\").addEventListener(\"click\",resetDataset);$(\"fileInput\").addEventListener(\"change\",event=>{const file=event.target.files?.[0];if(file)importFromFile(file)});[\"keyword\",\"platform\",\"region\"].forEach(id=>{$(id).addEventListener(\"input\",renderResults);$(id).addEventListener(\"change\",renderResults)});$(\"keyword\").addEventListener(\"keydown\",event=>{if(event.key===\"Enter\")renderResults()});renderDatasetStats();renderImportStatus(\"目前使用內建範例資料。你可以貼 JSON 或上傳檔案來擴充。\",\"info\");renderResults();";
export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname.endsWith("/styles.css")) {
      return new Response(css, { headers: { "content-type": "text/css; charset=utf-8" } });
    }
    if (url.pathname.endsWith("/script.js")) {
      return new Response(script, { headers: { "content-type": "application/javascript; charset=utf-8" } });
    }
    return new Response(html, { headers: { "content-type": "text/html; charset=utf-8" } });
  }
};